// Native logging = the website's Batch Log (MediaFlow v554), applied to the
// account state exactly as the website applies it. Order mirrors the website's
// wrapper chain around App.submitBatchLog:
//
//   base submitBatchLog (sessions + Library progress + completion timeline)
//     └ persistLibrary hooks: v334 first-start XP, v348 award multiplier + completion bonus
//   v120 logged-completion XP → v121 repeat XP → v137 start dates →
//   v252 per-season progress → v348 Batch Log bonus → v149 streak annotations
//
// Verified against golden fixtures generated by the real website
// (test/logging_golden_test.dart, tool/website_reference/).

import '../state/models.dart';
import '../util/js.dart';
import 'leveling.dart';

/// One title in a log. Give [reached] ("Episode reached", the website's default
/// Progress mode) or [amount] (Amount mode).
class LogEntry {
  const LogEntry({required this.libraryId, this.reached, this.amount, this.minutes});
  final String libraryId;
  final double? reached;
  final double? amount;
  final double? minutes;

  Map<String, dynamic> toJson() => {
        'libraryId': libraryId,
        if (reached != null) 'reached': jsOut(reached!),
        if (amount != null) 'amount': jsOut(amount!),
        if (minutes != null) 'minutes': jsOut(minutes!),
      };

  static LogEntry fromJson(Map<String, dynamic> j) => LogEntry(
        libraryId: jsStr(j['libraryId']),
        reached: j['reached'] == null ? null : jsNum(j['reached']),
        amount: j['amount'] == null ? null : jsNum(j['amount']),
        minutes: j['minutes'] == null ? null : jsNum(j['minutes']),
      );
}

/// A log the user submitted. All ids are generated once, up front, so the same
/// log can be re-applied to a newer cloud copy without creating duplicates.
class LogRequest {
  LogRequest({
    required this.entries,
    required this.createdAt,
    required this.sessionIds,
    required this.groupId,
    required this.eventId,
    this.note = '',
    this.date,
  });

  factory LogRequest.create(List<LogEntry> entries, {String note = '', String? date, int? now}) {
    final t = now ?? DateTime.now().millisecondsSinceEpoch;
    return LogRequest(
      entries: entries,
      createdAt: t,
      note: note,
      date: date,
      sessionIds: [for (var i = 0; i < entries.length; i++) mediaFlowUid(t)],
      groupId: mediaFlowUid(t),
      eventId: mediaFlowUid(t),
    );
  }

  final List<LogEntry> entries;
  final int createdAt;
  final String note;
  final String? date; // YYYY-MM-DD; null = today
  final List<String> sessionIds;
  final String groupId;
  final String eventId;

  Map<String, dynamic> toJson() => {
        'entries': entries.map((e) => e.toJson()).toList(),
        'createdAt': createdAt,
        'note': note,
        'date': date,
        'sessionIds': sessionIds,
        'groupId': groupId,
        'eventId': eventId,
      };

  static LogRequest fromJson(Map<String, dynamic> j) => LogRequest(
        entries: asList(j['entries']).map((e) => LogEntry.fromJson(asMap(e) ?? const {})).toList(),
        createdAt: jsNum(j['createdAt']).toInt(),
        note: jsStr(j['note']),
        date: j['date'] is String ? j['date'] as String : null,
        sessionIds: asList(j['sessionIds']).map(jsStr).toList(),
        groupId: jsStr(j['groupId']),
        eventId: jsStr(j['eventId']),
      );
}

class LogOutcome {
  LogOutcome({required this.applied, this.alreadyApplied = false});
  final bool applied;
  final bool alreadyApplied;
  final List<String> sessionIds = [];
  final List<String> titles = [];
  final List<String> completed = [];
  double xp = 0;
}

/// Quantity and minutes a Library title would get for [entry] (used by the UI
/// preview and by [applyLog]).
({double qty, double minutes, double start, double end}) previewEntry(
    LibraryTitle item, Category cat, LogEntry entry) {
  double qty;
  final double start = item.logStart;
  double end;
  final progressMode = entry.reached != null;
  if (progressMode) {
    end = clampEndProgress(item, entry.reached!);
    qty = end - start < 0 ? 0 : end - start;
  } else {
    qty = entry.amount == null || entry.amount! < 0 ? 0 : entry.amount!;
    end = start + qty;
  }
  var minutes = entry.minutes == null || entry.minutes! < 0 ? 0.0 : entry.minutes!;
  // Progress mode (v179): missing/zero minutes default to amount × minutes-per-unit.
  // Amount mode: only a missing value defaults.
  if ((progressMode && minutes <= 0) || (!progressMode && entry.minutes == null)) {
    minutes = jsRound(qty * cat.minutesPerUnit);
  }
  return (qty: qty, minutes: minutes, start: start, end: end);
}

/// `v179ClampEndProgress`.
double clampEndProgress(LibraryTitle item, double value) {
  var end = value < 0 ? 0.0 : value;
  final total = jsNumOrNull(item.raw['total']);
  if (item.raw['total'] != null && total != null && total > 0 && end > total) end = total;
  return end;
}

/// Applies [req] to [state] in place. Returns what changed. Re-applying a
/// request whose log ids are already in History is a no-op.
LogOutcome applyLog(Map<String, dynamic> state, LogRequest req) {
  final sessions = _list(state, 'sessions');
  final existingIds = sessions.map((s) => jsStr(asMap(s)?['id'])).toSet();
  if (req.sessionIds.any(existingIds.contains)) {
    return LogOutcome(applied: false, alreadyApplied: true);
  }

  final now = req.createdAt;
  final l = Leveling(state);
  final view = AccountView(state);
  final library = view.library;
  final byId = <String, LibraryTitle>{};
  for (final item in library) {
    byId.putIfAbsent(item.id, () => item);
  }
  final ledger = _map(state, 'xpLedger');

  // Snapshots taken before the log (v120 / v334 / v348 "known" states).
  final wasCompleted = {for (final i in library) i.id: i.isCompleted};
  final wasStarted = {for (final i in library) i.id: _started(i.raw)};
  final startedBefore = Map<String, dynamic>.from(_map(ledger, 'v334StartedTitles'));

  // ---- base submitBatchLog ---------------------------------------------------
  final today = isoDateUtc(now);
  final date = req.date != null && isIsoDay(req.date) ? req.date! : today;
  final timestamp = date == today ? now : (localNoonMs(date) ?? now);
  final outcome = LogOutcome(applied: true);
  final newSessions = <Map<String, dynamic>>[];

  for (var i = 0; i < req.entries.length; i++) {
    final entry = req.entries[i];
    final item = byId[entry.libraryId];
    if (item == null) continue;
    final cat = view.category(item.categoryId);
    final p = previewEntry(item, cat, entry);
    final qty = p.qty;
    if (!(qty > 0)) continue;
    final minutes = p.minutes;
    final health = categoryStatus(cat, sessions, now);
    final xp = l.consumptionXP(cat, qty, minutes, health);
    final repeat = item.isCompleted;
    final session = <String, dynamic>{
      'id': i < req.sessionIds.length ? req.sessionIds[i] : mediaFlowUid(now),
      'timestamp': timestamp,
      'date': date,
      'categoryId': cat.id,
      'targetAmount': jsOut(qty),
      'actualAmount': jsOut(qty),
      'minutes': jsOut(minutes),
      'note': req.note.trim(),
      'status': 'logged',
      'unit': cat.unit,
      'xp': jsOut(xp),
      'healthStatus': health,
      'source': 'batch',
      'batchGroupId': req.groupId,
      'titles': <dynamic>[
        <String, dynamic>{'title': cleanTitle(item.raw['title']), 'libraryId': item.id, 'qty': jsOut(qty), 'repeat': repeat, 'loggedAt': timestamp},
      ],
    };
    sessions.add(session);
    newSessions.add(session);
    outcome.sessionIds.add(jsStr(session['id']));
    outcome.titles.add(item.title);

    if (repeat) continue; // rewatch/reread: Library progress stays at the total
    final raw = item.raw;
    var progress = jsNum(raw['progress']) + qty;
    final total = jsNumOrNull(raw['total']);
    final hasTotal = jsTruthy(raw['total']);
    final double cap = total ?? 0.0;
    if (hasTotal) progress = progress < cap ? progress : cap;
    raw['progress'] = jsOut(progress);
    if (hasTotal && total != null && progress >= total && raw['status'] != 'dropped') {
      raw['status'] = 'completed';
      if (!jsTruthy(raw['completedAt'])) raw['completedAt'] = timestamp;
      final timeline = _list(state, 'completionTimeline');
      if (!timeline.any((x) => jsStr(asMap(x)?['libraryId']) == item.id)) {
        timeline.add(<String, dynamic>{
          'libraryId': item.id, 'title': cleanTitle(raw['title']), 'categoryId': raw['categoryId'],
          'completedAt': raw['completedAt'],
        });
      }
    } else if (raw['status'] == 'planned') {
      raw['status'] = 'active';
    }
  }
  if (newSessions.isEmpty) return LogOutcome(applied: false);

  // ---- persistLibrary hooks ---------------------------------------------------
  final multiplier = awardMultiplier(l, sessions, now);
  var metaSeq = 0;
  String metaUid() => '${req.eventId}_${metaSeq++}';
  final meta = _map(ledger, 'v348EventMeta');

  // v334: first time a title becomes "started".
  final startedTitles = _map(ledger, 'v334StartedTitles');
  for (final item in library) {
    final id = item.id;
    if (id.isEmpty) continue;
    if (wasStarted[id] == false && _started(item.raw) && !startedTitles.containsKey(id)) {
      startedTitles[id] = l.enabled ? jsOut(jsRound(l.reward('firstTitleStartXP'))) : 0;
    }
  }
  // v348RaiseNewRewards for v334StartedTitles.
  if (l.enabled) {
    for (final e in startedTitles.entries.toList()) {
      final prior = jsNum(startedBefore[e.key]);
      final added = jsNum(e.value) - prior;
      if (added > 0) {
        final xp = jsRound(added * multiplier);
        final inc = xp - added;
        if (inc > 0) startedTitles[e.key] = jsOut(jsNum(e.value) + inc);
        meta['v334StartedTitles:${e.key}:$now:${metaUid()}'] = {
          'kind': 'v334StartedTitles', 'baseXP': jsOut(added), 'multiplier': jsOut(multiplier), 'xp': jsOut(xp),
          'timestamp': now, 'source': 'First title start', 'subjectId': e.key,
        };
        outcome.xp += xp;
      }
    }
    // v348: award-time streak bonus on top of base completion XP.
    final completionBonus = _map(ledger, 'v348LibraryCompletionBonus');
    for (final item in library) {
      final id = item.id;
      if (id.isEmpty || !wasCompleted.containsKey(id)) continue;
      if (wasCompleted[id] == false && item.isCompleted && !completionBonus.containsKey(id)) {
        final amount = l.completionXP;
        final xp = jsRound(amount * multiplier);
        completionBonus[id] = jsOut(xp - amount < 0 ? 0 : xp - amount);
        meta['library-complete:$id'] = {
          'kind': 'completedLibrary', 'baseXP': jsOut(amount), 'multiplier': jsOut(multiplier), 'xp': jsOut(xp),
          'timestamp': now, 'source': 'Library · title completed', 'subjectId': id,
        };
        outcome.xp += xp;
      }
    }
  }

  // ---- v120: logged-completion XP -------------------------------------------
  for (final item in library) {
    if (wasCompleted[item.id] == false && item.isCompleted) {
      outcome.completed.add(item.title);
      if (!l.enabled) continue;
      final logCompletions = _map(ledger, 'logCompletions');
      if (!logCompletions.containsKey(item.id)) {
        logCompletions[item.id] = jsOut(l.loggingCompletionBonusXP);
        outcome.xp += l.loggingCompletionBonusXP;
      }
    }
  }

  // ---- v121/v134: repeat XP across History when a rewatch was logged ---------
  final hasRepeat = newSessions.any((s) => asList(s['titles']).any((t) {
        final m = asMap(t);
        return m != null && m['repeat'] == true && jsNum(m['qty']) > 0;
      }));
  if (hasRepeat) recalculateRepeatXP(state, l);

  // ---- v137: automatic start dates -------------------------------------------
  _reconcileStarts(state, newSessions, now);

  // ---- v252: spread aggregate progress over seasons --------------------------
  final touched = <String>{};
  for (final entry in req.entries) {
    final item = byId[entry.libraryId];
    if (item == null || touched.contains(item.id)) continue;
    touched.add(item.id);
    if (normalizeSeasons(item.raw['seasons'], jsStr(item.raw['seasonSource']).isEmpty ? 'manual' : jsStr(item.raw['seasonSource'])).isNotEmpty) {
      _distributeSeasonProgress(item.raw, jsNum(item.raw['progress']), now, req.eventId);
      item.raw['modifiedAt'] = now;
    }
  }

  // ---- v348: Batch Log bonus -------------------------------------------------
  if (l.enabled) {
    final rate = l.reward('batchLogXP');
    final xp = jsRound(rate * multiplier);
    if (xp > 0) {
      final key = 'batchLogXP:${req.eventId}';
      _map(ledger, 'v348ActionEvents')[key] = jsOut(xp);
      meta[key] = {
        'kind': 'batchLogXP', 'baseXP': jsOut(rate), 'multiplier': jsOut(multiplier), 'xp': jsOut(xp),
        'timestamp': now, 'source': 'Batch Log bonus', 'details': 'Successfully submitted a Batch Log entry',
        'subjectId': '', 'quantity': 1,
      };
      outcome.xp += xp;
    }
  }

  // ---- v149: streak annotations on every log ---------------------------------
  annotateStreakXP(state, l);
  for (final s in newSessions) {
    outcome.xp += jsNum(s['xpWithStreak']);
  }

  state['savedAt'] = now;
  return outcome;
}

bool _started(Map<String, dynamic> item) =>
    item['status'] == 'active' || jsNum(item['progress']) > 0 || jsNum(item['startedAt']) > 0;

List<dynamic> _list(Map<String, dynamic> parent, String key) {
  final v = parent[key];
  if (v is List) return v;
  final created = <dynamic>[];
  parent[key] = created;
  return created;
}

Map<String, dynamic> _map(Map<String, dynamic> parent, String key) {
  final v = parent[key];
  if (v is Map<String, dynamic>) return v;
  if (v is Map) {
    final cast = v.cast<String, dynamic>();
    parent[key] = cast;
    return cast;
  }
  final created = <String, dynamic>{};
  parent[key] = created;
  return created;
}

// ---- v121 / v134 repeat XP ----------------------------------------------------

/// `v121RecalculateRepeatXPHistory` (v134 implementation).
void recalculateRepeatXP(Map<String, dynamic> state, Leveling l) {
  final view = AccountView(state);
  final libraryById = <String, Map<String, dynamic>>{};
  for (final item in view.library) {
    if (item.id.isNotEmpty) libraryById.putIfAbsent(item.id, () => item.raw);
  }
  final sessions = asList(state['sessions']);
  final rows = <({Map<String, dynamic> s, int index, double time})>[];
  for (var i = 0; i < sessions.length; i++) {
    final s = asMap(sessions[i]);
    if (s != null) rows.add((s: s, index: i, time: _sessionTime(s)));
  }
  rows.sort((a, b) {
    final d = a.time.compareTo(b.time);
    return d != 0 ? d : a.index.compareTo(b.index);
  });
  final running = <String, double>{};
  for (final row in rows) {
    final s = row.s;
    if (s['status'] == 'skipped') continue;
    double units = 0, full = 0, unitXP = 0, fullXP = 0;
    for (final rawT in asList(s['titles'])) {
      final t = asMap(rawT);
      if (t == null) continue;
      final unitsList = t['v369Units'];
      final itemized = unitsList is List && t['v369Itemized'] == true;
      if (t['repeat'] != true && !itemized) continue;
      final double qty = itemized
          ? unitsList.where((u) => t['repeat'] == true || asMap(u)?['isRepeat'] == true).length.toDouble()
          : (jsNum(t['qty']) < 0 ? 0.0 : jsNum(t['qty']));
      if (qty <= 0) continue;
      final item = jsTruthy(t['libraryId']) ? libraryById[jsStr(t['libraryId'])] : null;
      final unit = view.category(jsStr(item?['categoryId'] ?? s['categoryId'])).unit;
      final double perUnit = l.enabled ? (l.repeatUnitXP(unit) < 0 ? 0.0 : l.repeatUnitXP(unit)) : 0.0;
      units += qty;
      unitXP += qty * perUnit;
      final key = _repeatKey(t, s);
      if (key.isNotEmpty) {
        final before = running[key] ?? 0;
        final after = before + qty;
        final total = _repeatTotal(t, item, unit);
        if (total > 0) {
          final crossed = (after / total).floor() - (before / total).floor();
          if (crossed > 0) {
            full += crossed;
            fullXP += l.enabled ? crossed * l.fullRepeatXP : 0.0;
          }
        }
        running[key] = after;
      }
    }
    final cat = view.category(jsStr(s['categoryId']));
    final health = jsStr(s['healthStatus']).isEmpty ? 'healthy' : jsStr(s['healthStatus']);
    if (units > 0) {
      final base = l.consumptionXP(cat, jsNum(s['actualAmount']), jsNum(s['minutes']), health);
      final unitBonus = jsRound(unitXP) < 0 ? 0.0 : jsRound(unitXP);
      final fullBonus = jsRound(fullXP) < 0 ? 0.0 : jsRound(fullXP);
      s['repeatUnits'] = jsOut(units);
      s['fullRepeatsCompleted'] = jsOut(full);
      s['repeatUnitBonusXP'] = jsOut(unitBonus);
      s['repeatFullTitleXP'] = jsOut(fullBonus);
      s['repeatBonusXP'] = jsOut(unitBonus + fullBonus);
      s['xp'] = jsOut(jsRound(base + unitBonus + fullBonus));
    } else if (s.containsKey('repeatBonusXP') || s.containsKey('repeatUnitBonusXP') ||
        s.containsKey('repeatFullTitleXP') || s.containsKey('repeatUnits') || s.containsKey('fullRepeatsCompleted')) {
      s['repeatUnits'] = 0;
      s['fullRepeatsCompleted'] = 0;
      s['repeatUnitBonusXP'] = 0;
      s['repeatFullTitleXP'] = 0;
      s['repeatBonusXP'] = 0;
      s['xp'] = jsOut(l.consumptionXP(cat, jsNum(s['actualAmount']), jsNum(s['minutes']), health));
    }
  }
}

double _sessionTime(Map<String, dynamic> s) {
  final direct = jsNum(s['timestamp']);
  if (direct > 0) return direct;
  final parsed = DateTime.tryParse('${jsStr(s['date'])}T12:00:00');
  return parsed == null ? 0 : parsed.millisecondsSinceEpoch.toDouble();
}

String _repeatKey(Map<String, dynamic> t, Map<String, dynamic> s) {
  if (jsTruthy(t['libraryId'])) return 'id:${jsStr(t['libraryId'])}';
  final title = cleanTitle(t['title']).toLowerCase();
  return title.isNotEmpty ? 'title:$title::${jsStr(s['categoryId'])}' : '';
}

double _repeatTotal(Map<String, dynamic> t, Map<String, dynamic>? item, String unit) {
  final stored = jsNum(t['repeatTotalAtLog']);
  if (stored > 0) return stored;
  final current = jsNum(item?['total']);
  final total = current > 0 ? current : (unit == 'movies' ? 1.0 : 0.0);
  if (total > 0) t['repeatTotalAtLog'] = jsOut(total);
  return total;
}

// ---- v137 start dates -----------------------------------------------------------

void _reconcileStarts(Map<String, dynamic> state, List<Map<String, dynamic>> added, int now) {
  final library = asList(state['library']).map(asMap).whereType<Map<String, dynamic>>().toList();
  final affected = <String, Map<String, dynamic>>{};
  for (final s in added) {
    if (s['status'] == 'skipped') continue;
    for (final rawT in asList(s['titles'])) {
      final t = asMap(rawT);
      if (t == null || t['repeat'] == true) continue;
      final item = _resolveHistoryTitle(library, s, t);
      if (item != null && jsTruthy(item['id'])) affected[jsStr(item['id'])] = item;
    }
  }
  final sessions = asList(state['sessions']).map(asMap).whereType<Map<String, dynamic>>().toList();
  for (final item in affected.values) {
    final canChange = !(jsNum(item['startedAt']) > 0) || jsStr(item['startedAtSource']) == 'auto';
    if (!canChange) continue;
    var earliest = double.infinity;
    for (final s in sessions) {
      if (s['status'] == 'skipped') continue;
      for (final rawT in asList(s['titles'])) {
        final t = asMap(rawT);
        if (t == null || !_isGenuineStart(item, s, t)) continue;
        final ts = _historyTimestamp(s);
        if (ts > 0 && ts < earliest) earliest = ts;
      }
    }
    if (!earliest.isFinite) continue;
    final current = jsNum(item['startedAt']);
    if (current > 0 && earliest >= current) continue;
    item['startedAt'] = jsOut(earliest);
    item['startedAtSource'] = 'auto';
    item['modifiedAt'] = now;
  }
}

Map<String, dynamic>? _resolveHistoryTitle(
    List<Map<String, dynamic>> library, Map<String, dynamic> session, Map<String, dynamic> row) {
  if (jsTruthy(row['libraryId'])) {
    for (final i in library) {
      if (jsStr(i['id']) == jsStr(row['libraryId'])) return i;
    }
  }
  final key = cleanTitle(row['title']).toLowerCase();
  if (key.isEmpty) return null;
  for (final i in library) {
    if (cleanTitle(i['title']).toLowerCase() == key && jsStr(i['categoryId']) == jsStr(session['categoryId'])) return i;
  }
  final all = library.where((i) => cleanTitle(i['title']).toLowerCase() == key).toList();
  return all.length == 1 ? all.first : null;
}

bool _isGenuineStart(Map<String, dynamic> item, Map<String, dynamic> session, Map<String, dynamic> row) {
  if (session['status'] == 'skipped' || row['repeat'] == true) return false;
  final matches = jsTruthy(row['libraryId'])
      ? jsStr(row['libraryId']) == jsStr(item['id'])
      : cleanTitle(row['title']).toLowerCase() == cleanTitle(item['title']).toLowerCase() &&
          jsStr(session['categoryId']) == jsStr(item['categoryId']);
  if (!matches) return false;
  final qtyRaw = row['qty'] ?? row['amount'];
  final hasQty = qtyRaw != null && qtyRaw != '';
  if (hasQty && jsNum(qtyRaw) <= 0) return false;
  return jsNum(session['actualAmount']) > 0 || jsNum(session['minutes']) > 0 || (hasQty && jsNum(qtyRaw) > 0);
}

double _historyTimestamp(Map<String, dynamic> s) {
  final raw = jsStr(s['date']).trim();
  final day = raw.length >= 10 ? raw.substring(0, 10) : raw;
  final fromDate = isIsoDay(day) ? (localNoonMs(day) ?? 0) : 0;
  if (fromDate > 0) return fromDate.toDouble();
  return jsNum(s['timestamp']);
}

// ---- v252 seasons -------------------------------------------------------------------

int? _seasonNumber(Object? v) {
  if (v == null || jsStr(v).trim().isEmpty) return null;
  final n = jsNumOrNull(v);
  if (n == null) return null;
  final r = jsRound(n);
  return (r < 0 ? 0 : r).toInt();
}

int _seasonNum(Object? v, int fallback) {
  final n = jsNumOrNull(v);
  if (n == null) return fallback;
  final r = jsRound(n);
  return (r < 0 ? 0 : r).toInt();
}

/// `v252NormalizeSeasons`.
List<Map<String, dynamic>> normalizeSeasons(Object? raw, String source, [String idSeed = 'season']) {
  final list = raw is List ? raw : const [];
  final out = <Map<String, dynamic>>[];
  for (var index = 0; index < list.length; index++) {
    out.add(_normalizeSeason(list[index], index, source, '$idSeed-$index'));
  }
  final indexed = [for (var i = 0; i < out.length; i++) (s: out[i], i: i)];
  indexed.sort((a, b) {
    final an = a.s['number'] as int?, bn = b.s['number'] as int?;
    if (an == null && bn == null) return a.i - b.i;
    if (an == null) return 1;
    if (bn == null) return -1;
    final d = an - bn;
    return d != 0 ? d : a.i - b.i;
  });
  return indexed.map((x) => x.s).toList();
}

Map<String, dynamic> _normalizeSeason(Object? raw, int index, String source, String fallbackId) {
  final row = asMap(raw) ?? const <String, dynamic>{};
  final number = _seasonNumber(row['number'] ?? row['season'] ?? row['season_number'] ?? row['seasonNumber']);
  final explicitTotal = row['total'] ?? row['totalEpisodes'] ?? row['total_episodes'] ??
      row['total_episodes_count'] ?? row['episodes_count'] ?? row['episode_count'];
  final int? total = (explicitTotal == null || jsStr(explicitTotal).trim().isEmpty) ? null : _seasonNum(explicitTotal, 0);
  var progress = _seasonNum(row['progress'] ?? row['watchedEpisodes'] ?? row['watched_episodes'] ??
      row['watched_episodes_count'] ?? row['episodes_watched'], 0);
  if (total != null && total > 0 && progress > total) progress = total;
  final src = jsStr(row['source']).isNotEmpty ? jsStr(row['source']) : (source.isNotEmpty ? source : 'manual');
  final name = cleanTitle(jsStr(row['name']).isNotEmpty ? row['name'] : row['title']);
  final id = jsTruthy(row['id']) ? row['id'] : (jsTruthy(row['seasonId']) ? row['seasonId'] : (jsTruthy(row['season_id']) ? row['season_id'] : fallbackId));
  return {
    'id': jsStr(id),
    'number': number,
    'name': name.isNotEmpty ? name : (number == 0 ? 'Specials' : number != null ? 'Season $number' : 'Season ${index + 1}'),
    'progress': progress,
    'total': total != null && total > 0 ? total : (total == 0 ? 0 : null),
    'source': src,
    'manual': row['manual'] == true || src == 'manual',
    'synthetic': row['synthetic'] == true,
  };
}

/// `v252DistributeAggregateProgress` + `v252SyncTitleFromSeasons`.
void _distributeSeasonProgress(Map<String, dynamic> item, double aggregate, int now, String idSeed) {
  final source = jsStr(item['seasonSource']).isEmpty ? 'manual' : jsStr(item['seasonSource']);
  final seasons = normalizeSeasons(item['seasons'], source, 'season-$idSeed');
  if (seasons.isEmpty) return;
  var remaining = aggregate < 0 ? 0.0 : aggregate;
  for (final season in seasons) {
    final t = season['total'] as int?;
    if (t != null && t > 0) {
      season['progress'] = jsOut(remaining < t ? remaining : t.toDouble());
      remaining = remaining - t < 0 ? 0.0 : remaining - t;
    } else {
      season['progress'] = jsOut(remaining);
      remaining = 0;
    }
  }
  if (remaining > 0) {
    final tail = seasons.last;
    if (jsNum(tail['total']) > 0) {
      seasons.add(_normalizeSeason({
        'name': 'Unassigned', 'progress': remaining, 'total': remaining, 'source': 'derived', 'synthetic': true,
      }, seasons.length, 'derived', 'season-$idSeed-unassigned'));
    } else {
      tail['progress'] = jsOut(jsNum(tail['progress']) + remaining);
    }
  }
  // v252SyncTitleFromSeasons
  final normalized = normalizeSeasons(seasons, source, 'season-$idSeed');
  item['seasons'] = normalized;
  var progress = 0, total = 0;
  for (final s in normalized) {
    progress += _seasonNum(s['progress'], 0);
    total += s['total'] == null ? 0 : _seasonNum(s['total'], 0);
  }
  item['progress'] = progress;
  item['total'] = total > 0 ? total : null;
  item['seasonViewEnabled'] = item['seasonViewEnabled'] != false;
  final prev = jsNum(item['seasonsModifiedAt']);
  item['seasonsModifiedAt'] = jsOut(prev > now ? prev : now.toDouble());
}
